import pytest

from apps.user.models.user.legacy import LegacyUser


# Generated by the original Python 3.11 crypt implementation, before migration.
@pytest.mark.parametrize(
    ("password", "salt", "expected"),
    [
        ("password", "ab", "abxzizGLrzGlc"),
        ("ara-legacy-user", "./", "./5dDbaMP7AgQ"),
        ("가나다password", "Xz", "XzI/PFsB7QcSg"),
        ("", "AA", "AAyhcyIasduxQ"),
    ],
)
def test_legacy_password_hash_matches_original_crypt(password, salt, expected):
    assert LegacyUser.encrypt_password(password, salt) == expected
    assert LegacyUser.encrypt_password(password, expected) == expected


def test_legacy_password_verification_accepts_only_matching_password():
    user = LegacyUser(password="abxzizGLrzGlc")
    assert user.compare_password("password")
    assert not user.compare_password("incorrect")
